package com.techpp.glass;

import android.content.Context;
import android.content.SharedPreferences;
import org.json.JSONObject;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * TV pairing client. Pairing codes are issued by an authorized companion/admin,
 * not generated by the TV itself. Never accepts an OpenAI API key.
 * Access tokens are short-lived and are kept in app-private storage.
 */
public final class AiTvPairingClient {
    public interface Callback {
        void onPaired();
        void onError(String message);
    }

    private static final String PREFS = "ai_tv_device_session";
    private static final String TOKEN = "access_token";
    private static final String EXPIRES = "expires_at";
    private final Context app;
    private final ExecutorService worker = Executors.newSingleThreadExecutor();

    public AiTvPairingClient(Context context) { app = context.getApplicationContext(); }

    public boolean hasSession() {
        SharedPreferences prefs = app.getSharedPreferences(PREFS, Context.MODE_PRIVATE);
        return prefs.getLong(EXPIRES, 0) > System.currentTimeMillis() + 30000
                && !prefs.getString(TOKEN, "").isEmpty();
    }

    public String currentToken() {
        return hasSession() ? app.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
                .getString(TOKEN, "") : "";
    }

    public void clearSession() {
        app.getSharedPreferences(PREFS, Context.MODE_PRIVATE).edit().clear().apply();
    }

    public void refresh(String gateway, Callback callback) {
        worker.execute(() -> {
            HttpURLConnection connection=null;
            try {
                String token=currentToken();
                if (token.isEmpty()) throw new IllegalStateException("Session expired");
                URL url=new URL(gateway.replaceAll("/+$","")+"/v1/pair/refresh");
                if (!"https".equalsIgnoreCase(url.getProtocol())) throw new IllegalArgumentException("HTTPS required");
                connection=(HttpURLConnection)url.openConnection();
                connection.setRequestMethod("POST");connection.setDoOutput(true);
                connection.setConnectTimeout(7000);connection.setReadTimeout(12000);
                connection.setRequestProperty("Authorization","Bearer "+token);
                try(OutputStream out=connection.getOutputStream()){out.write(new byte[0]);}
                if(connection.getResponseCode()!=200) throw new IllegalStateException("Session rejected");
                try(InputStream in=connection.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){
                    byte[] b=new byte[1024];int n;
                    while((n=in.read(b))!=-1){if(out.size()+n>8192)throw new IllegalStateException("Response too large");out.write(b,0,n);}
                    JSONObject result=new JSONObject(out.toString("UTF-8"));
                    long ttl=result.getLong("expiresIn");
                    if(ttl<60 || ttl>3600)throw new IllegalStateException("Invalid TTL");
                    app.getSharedPreferences(PREFS,Context.MODE_PRIVATE).edit()
                        .putString(TOKEN,result.getString("accessToken"))
                        .putLong(EXPIRES,System.currentTimeMillis()+ttl*1000L).apply();
                    callback.onPaired();
                }
            } catch(Exception e){clearSession();callback.onError("Session expired. Pair this TV again.");}
            finally {if(connection!=null)connection.disconnect();}
        });
    }

    public void exchange(String gateway, String code, Callback callback) {
        worker.execute(() -> {
            HttpURLConnection connection = null;
            try {
                if (!code.matches("[0-9a-fA-F]{10}"))
                    throw new IllegalArgumentException("Invalid pairing code");
                URL url = new URL(gateway.replaceAll("/+$", "") + "/v1/pair/exchange");
                if (!"https".equalsIgnoreCase(url.getProtocol()))
                    throw new IllegalArgumentException("HTTPS required");
                connection = (HttpURLConnection) url.openConnection();
                connection.setRequestMethod("POST");
                connection.setDoOutput(true);
                connection.setConnectTimeout(7000);
                connection.setReadTimeout(12000);
                connection.setRequestProperty("Content-Type", "application/json");
                byte[] request = new JSONObject().put("code", code.toUpperCase())
                        .toString().getBytes(StandardCharsets.UTF_8);
                try (OutputStream out = connection.getOutputStream()) { out.write(request); }
                if (connection.getResponseCode() != 200)
                    throw new IllegalStateException("Code expired or rejected");
                try (InputStream in = connection.getInputStream();
                     ByteArrayOutputStream buffer = new ByteArrayOutputStream()) {
                    byte[] chunk = new byte[1024];
                    int n;
                    while ((n = in.read(chunk)) != -1) {
                        if (buffer.size() + n > 8192) throw new IllegalStateException("Response too large");
                        buffer.write(chunk, 0, n);
                    }
                    JSONObject result = new JSONObject(buffer.toString("UTF-8"));
                    String token = result.getString("accessToken");
                    long expiresIn = result.getLong("expiresIn");
                    if (token.isEmpty() || expiresIn < 60 || expiresIn > 3600)
                        throw new IllegalStateException("Invalid session");
                    app.getSharedPreferences(PREFS, Context.MODE_PRIVATE).edit()
                            .putString(TOKEN, token)
                            .putLong(EXPIRES, System.currentTimeMillis() + expiresIn * 1000L)
                            .apply();
                    callback.onPaired();
                }
            } catch (Exception e) {
                callback.onError("Unable to pair TV. Check the code and connection.");
            } finally {
                if (connection != null) connection.disconnect();
            }
        });
    }
}
